// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { c = new PoCGame(address(this), 0); }
    function testFuzz_property(uint256 difficultyChange, address caller) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));
        uint256 originalDifficulty = c.currentDifficulty();
        vm.prank(caller);
        try c.AdjustDifficulty(difficultyChange) { } catch { }
        c.AdjustBetAmounts(0);
        assertTrue(c.currentDifficulty() == originalDifficulty);
    }
}
